  1→"use client";
  2→
  3→import { useState } from "react";
  4→import type { UserRecord, UserRole } from "@/lib/types";
  5→
  6→type UserAdminPanelProps = {
  7→  initialUsers: UserRecord[];
  8→  departments: Array<{ deptCode: string; deptName: string }>;
  9→};
 10→
 11→const ROLES: UserRole[] = ["VIP", "ADMIN", "DEAN"];
 12→
 13→export function UserAdminPanel({ initialUsers, departments }: UserAdminPanelProps) {
 14→  const [users, setUsers] = useState(initialUsers);
 15→  const [form, setForm] = useState({
 16→    username: "",
 17→    password: "",
 18→    role: "DEAN" as UserRole,
 19→    departmentCode: departments[0]?.deptCode ?? "",
 20→  });
 21→  const [message, setMessage] = useState("");
 22→
 23→  async function refreshUsers() {
 24→    const response = await fetch("/api/users");
 25→    const data = (await response.json()) as { users: UserRecord[] };
 26→    setUsers(data.users);
 27→  }
 28→
 29→  async function handleCreate(event: React.FormEvent<HTMLFormElement>) {
 30→    event.preventDefault();
 31→    const response = await fetch("/api/users", {
 32→      method: "POST",
 33→      headers: { "Content-Type": "application/json" },
 34→      body: JSON.stringify(form),
 35→    });
 36→    const data = (await response.json()) as { message?: string };
 37→    if (!response.ok) {
 38→      setMessage(data.message ?? "사용자 생성에 실패했습니다.");
 39→      return;
 40→    }
 41→    setMessage("사용자를 생성했습니다.");
 42→    setForm({
 43→      username: "",
 44→      password: "",
 45→      role: "DEAN",
 46→      departmentCode: departments[0]?.deptCode ?? "",
 47→    });
 48→    await refreshUsers();
 49→  }
 50→
 51→  async function handleRoleChange(user: UserRecord, role: UserRole) {
 52→    await fetch(`/api/users/${user.id}`, {
 53→      method: "PATCH",
 54→      headers: { "Content-Type": "application/json" },
 55→      body: JSON.stringify({ role, departmentCode: role === "DEAN" ? user.departmentCode : null }),
 56→    });
 57→    await refreshUsers();
 58→  }
 59→
 60→  return (
 61→    <section>
 62→      <div>
 63→        <h2 style={{ fontSize: 18, fontWeight: 600, color: "var(--text-title)", margin: 0 }}>사용자 관리</h2>
 64→        <p style={{ fontSize: 12, color: "var(--text-secondary)", marginTop: 4 }}>VIP만 사용자 계정과 역할을 관리할 수 있습니다.</p>
 65→      </div>
 66→
 67→      <div className="mt-6 grid gap-6 xl:grid-cols-[0.9fr_1.1fr]">
 68→        {/* Create form */}
 69→        <form onSubmit={handleCreate} className="card space-y-4" style={{ background: "var(--row-hover)", border: "1px solid var(--divider)" }}>
 70→          <h3 style={{ fontSize: 14, fontWeight: 600, color: "var(--text-title)", margin: 0 }}>사용자 추가</h3>
 71→          <input
 72→            value={form.username}
 73→            onChange={(event) => setForm((current) => ({ ...current, username: event.target.value }))}
 74→            placeholder="username"
 75→            className="input"
 76→            style={{ width: "100%" }}
 77→          />
 78→          <input
 79→            value={form.password}
 80→            onChange={(event) => setForm((current) => ({ ...current, password: event.target.value }))}
 81→            placeholder="temporary password"
 82→            className="input"
 83→            style={{ width: "100%" }}
 84→          />
 85→          <select
 86→            value={form.role}
 87→            onChange={(event) => setForm((current) => ({ ...current, role: event.target.value as UserRole }))}
 88→            className="input"
 89→            style={{ width: "100%" }}
 90→          >
 91→            {ROLES.map((role) => (
 92→              <option key={role} value={role}>
 93→                {role}
 94→              </option>
 95→            ))}
 96→          </select>
 97→          <select
 98→            value={form.departmentCode}
 99→            onChange={(event) => setForm((current) => ({ ...current, departmentCode: event.target.value }))}
100→            className="input"
101→            style={{ width: "100%" }}
102→          >
103→            {departments.map((department) => (
104→              <option key={department.deptCode} value={department.deptCode}>
105→                {department.deptName}
106→              </option>
107→            ))}
108→          </select>
109→          <button className="btn-primary">계정 생성</button>
110→          {message ? <p style={{ fontSize: 13, color: "var(--primary-green)" }}>{message}</p> : null}
111→        </form>
112→
113→        {/* User list */}
114→        <div className="card" style={{ background: "var(--row-hover)", border: "1px solid var(--divider)" }}>
115→          <h3 style={{ fontSize: 14, fontWeight: 600, color: "var(--text-title)", margin: 0 }}>사용자 목록</h3>
116→          <div style={{ marginTop: 12 }} className="space-y-3">
117→            {users.map((user) => (
118→              <div
119→                key={user.id}
120→                className="card"
121→                style={{
122→                  display: "flex",
123→                  flexWrap: "wrap",
124→                  gap: 12,
125→                  alignItems: "center",
126→                  justifyContent: "space-between",
127→                  padding: "12px 16px",
128→                  background: "var(--card-bg)",
129→                  border: "1px solid var(--divider)",
130→                }}
131→              >
132→                <div>
133→                  <p style={{ fontSize: 13, fontWeight: 600, color: "var(--text-title)", margin: 0 }}>{user.username}</p>
134→                  <p style={{ marginTop: 4, fontSize: 11, color: "var(--text-secondary)" }}>
135→                    {user.role}
136→                    {user.departmentCode ? ` \u00B7 ${user.departmentCode}` : ""}
137→                  </p>
138→                </div>
139→                <select
140→                  value={user.role}
141→                  onChange={(event) => handleRoleChange(user, event.target.value as UserRole)}
142→                  className="input"
143→                  style={{ fontSize: 11, padding: "4px 10px" }}
144→                >
145→                  {ROLES.map((role) => (
146→                    <option key={role} value={role}>
147→                      {role}
148→                    </option>
149→                  ))}
150→                </select>
151→              </div>
152→            ))}
153→          </div>
154→        </div>
155→      </div>
156→    </section>
157→  );
158→}
