  1→"use client";
  2→
  3→import { useState } from "react";
  4→
  5→type PermissionEntry = {
  6→  resource: string;
  7→  action: string;
  8→  allowed: boolean;
  9→};
 10→
 11→type Props = {
 12→  roles: string[];
 13→  permissions: Record<string, PermissionEntry[]>;
 14→};
 15→
 16→const RESOURCE_GROUPS: { title: string; resources: { key: string; label: string }[] }[] = [
 17→  {
 18→    title: "대시보드",
 19→    resources: [
 20→      { key: "dashboard", label: "채용현황 (요약/TO배분표/진행현황)" },
 21→    ],
 22→  },
 23→  {
 24→    title: "후보자",
 25→    resources: [{ key: "candidates", label: "후보자 관리" }],
 26→  },
 27→  {
 28→    title: "채용 절차",
 29→    resources: [
 30→      { key: "procedures", label: "채용 절차 상세" },
 31→      { key: "actions", label: "단계별 제출" },
 32→    ],
 33→  },
 34→  {
 35→    title: "관리",
 36→    resources: [
 37→      { key: "admin.data", label: "데이터 관리 (채용요청/워크플로우)" },
 38→    ],
 39→  },
 40→  {
 41→    title: "워크플로우",
 42→    resources: [
 43→      { key: "workflow.review", label: "초빙위원회 심사" },
 44→      { key: "workflow.advance", label: "다음 단계 승인" },
 45→    ],
 46→  },
 47→  {
 48→    title: "시스템",
 49→    resources: [
 50→      { key: "system.permissions", label: "권한 관리" },
 51→      { key: "system.users", label: "사용자 관리" },
 52→    ],
 53→  },
 54→  {
 55→    title: "기타",
 56→    resources: [{ key: "etc", label: "기타" }],
 57→  },
 58→];
 59→
 60→const ACTIONS = [
 61→  { key: "view", label: "보기" },
 62→  { key: "edit", label: "편집" },
 63→  { key: "delete", label: "삭제" },
 64→  { key: "export", label: "내보내기" },
 65→  { key: "import", label: "가져오기" },
 66→];
 67→
 68→export default function PermissionMatrix({ roles, permissions }: Props) {
 69→  const [activeRole, setActiveRole] = useState(roles[0] || "ADMIN");
 70→  const [localPerms, setLocalPerms] = useState(permissions);
 71→  const [saving, setSaving] = useState(false);
 72→  const [newRole, setNewRole] = useState("");
 73→  const [message, setMessage] = useState("");
 74→
 75→  function isAllowed(role: string, resource: string, action: string): boolean {
 76→    const perms = localPerms[role] || [];
 77→    const wildcard = perms.find((p) => p.resource === "*" && p.action === action);
 78→    if (wildcard) return wildcard.allowed;
 79→    const entry = perms.find((p) => p.resource === resource && p.action === action);
 80→    return entry?.allowed ?? false;
 81→  }
 82→
 83→  function toggle(resource: string, action: string) {
 84→    const current = isAllowed(activeRole, resource, action);
 85→    setLocalPerms((prev) => {
 86→      const rolePerms = [...(prev[activeRole] || [])];
 87→      const idx = rolePerms.findIndex(
 88→        (p) => p.resource === resource && p.action === action
 89→      );
 90→      if (idx >= 0) {
 91→        rolePerms[idx] = { ...rolePerms[idx], allowed: !current };
 92→      } else {
 93→        rolePerms.push({ resource, action, allowed: !current });
 94→      }
 95→      return { ...prev, [activeRole]: rolePerms };
 96→    });
 97→  }
 98→
 99→  async function save() {
100→    setSaving(true);
101→    setMessage("");
102→    const original = permissions[activeRole] || [];
103→    const current = localPerms[activeRole] || [];
104→    const changes: { resource: string; action: string; allowed: boolean }[] = [];
105→
106→    for (const c of current) {
107→      const orig = original.find(
108→        (o) => o.resource === c.resource && o.action === c.action
109→      );
110→      if (!orig || orig.allowed !== c.allowed) {
111→        changes.push(c);
112→      }
113→    }
114→
115→    if (changes.length > 0) {
116→      await fetch("/api/permissions", {
117→        method: "PATCH",
118→        headers: { "Content-Type": "application/json" },
119→        body: JSON.stringify({ role: activeRole, changes }),
120→      });
121→      setMessage("권한이 저장되었습니다.");
122→    } else {
123→      setMessage("변경사항이 없습니다.");
124→    }
125→    setSaving(false);
126→  }
127→
128→  async function addRole() {
129→    if (!newRole.trim()) return;
130→    await fetch("/api/roles", {
131→      method: "POST",
132→      headers: { "Content-Type": "application/json" },
133→      body: JSON.stringify({ role: newRole.trim() }),
134→    });
135→    window.location.reload();
136→  }
137→
138→  // 역할 탭 순서: ADMIN → DEAN → VIP → 나머지
139→  const sortedRoles = [...roles].sort((a, b) => {
140→    const order: Record<string, number> = { ADMIN: 0, DEAN: 1, VIP: 2 };
141→    return (order[a] ?? 3) - (order[b] ?? 3);
142→  });
143→
144→  return (
145→    <div>
146→      {/* Header */}
147→      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 20, flexWrap: "wrap", gap: 12 }}>
148→        <div>
149→          <h2 style={{ fontSize: 18, fontWeight: 600, color: "var(--text-title)", margin: 0 }}>
150→            권한 관리
151→          </h2>
152→          <p style={{ fontSize: 12, color: "var(--text-secondary)", margin: "2px 0 0" }}>
153→            역할별 페이지 및 기능 접근 권한을 설정합니다
154→          </p>
155→        </div>
156→        <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
157→          <div style={{ display: "flex", gap: 4 }}>
158→            <input
159→              value={newRole}
160→              onChange={(e) => setNewRole(e.target.value)}
161→              placeholder="새 역할명"
162→              className="input"
163→              style={{ width: 120 }}
164→            />
165→            <button className="btn-secondary" onClick={addRole}>
166→              + 추가
167→            </button>
168→          </div>
169→          <button className="btn-primary" onClick={save} disabled={saving}>
170→            {saving ? "저장 중..." : "변경사항 저장"}
171→          </button>
172→        </div>
173→      </div>
174→
175→      {/* Role tabs */}
176→      <div style={{ display: "flex", gap: 4, marginBottom: 20 }}>
177→        {sortedRoles.map((role) => (
178→          <button
179→            key={role}
180→            onClick={() => setActiveRole(role)}
181→            style={{
182→              padding: "8px 16px",
183→              background: role === activeRole ? "var(--deep-green)" : "var(--card-bg)",
184→              color: role === activeRole ? "#fff" : "var(--text-body)",
185→              border: role === activeRole ? "none" : "1px solid var(--divider)",
186→              borderRadius: 6,
187→              fontSize: 12,
188→              fontWeight: role === activeRole ? 500 : 400,
189→              cursor: "pointer",
190→            }}
191→          >
192→            {role}
193→          </button>
194→        ))}
195→      </div>
196→
197→      {/* Matrix table */}
198→      <div className="card" style={{ padding: 0, overflow: "hidden" }}>
199→        <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 12 }}>
200→          <thead>
201→            <tr style={{ background: "var(--header-bg)" }}>
202→              <th style={{ textAlign: "left", padding: "10px 14px", color: "var(--text-secondary)", fontWeight: 500, fontSize: 11, width: "30%" }}>
203→                리소스
204→              </th>
205→              {ACTIONS.map((a) => (
206→                <th key={a.key} style={{ textAlign: "center", padding: "10px 14px", color: "var(--text-secondary)", fontWeight: 500, fontSize: 11, width: "14%" }}>
207→                  {a.label}
208→                </th>
209→              ))}
210→            </tr>
211→          </thead>
212→          <tbody>
213→            {RESOURCE_GROUPS.map((group) => (
214→              <tbody key={group.title}>
215→                <tr style={{ background: "var(--header-bg)" }}>
216→                  <td
217→                    colSpan={6}
218→                    style={{
219→                      padding: "8px 14px",
220→                      fontSize: 10,
221→                      color: "var(--text-secondary)",
222→                      fontWeight: 600,
223→                      textTransform: "uppercase",
224→                      letterSpacing: 0.5,
225→                    }}
226→                  >
227→                    {group.title}
228→                  </td>
229→                </tr>
230→                {group.resources.map((res) => (
231→                  <tr key={res.key} style={{ borderTop: "1px solid var(--divider)" }}>
232→                    <td style={{ padding: "10px 14px", color: "var(--text-body)" }}>
233→                      {res.label}
234→                    </td>
235→                    {ACTIONS.map((action) => {
236→                      const allowed = isAllowed(activeRole, res.key, action.key);
237→                      return (
238→                        <td key={action.key} style={{ textAlign: "center", padding: "10px 14px" }}>
239→                          <div
240→                            onClick={() => toggle(res.key, action.key)}
241→                            style={{
242→                              width: 18,
243→                              height: 18,
244→                              background: allowed ? "var(--primary-green)" : "#e0e0e0",
245→                              borderRadius: 4,
246→                              margin: "0 auto",
247→                              display: "flex",
248→                              alignItems: "center",
249→                              justifyContent: "center",
250→                              cursor: "pointer",
251→                            }}
252→                          >
253→                            {allowed && (
254→                              <span style={{ color: "#fff", fontSize: 11 }}>&#10003;</span>
255→                            )}
256→                          </div>
257→                        </td>
258→                      );
259→                    })}
260→                  </tr>
261→                ))}
262→              </tbody>
263→            ))}
264→          </tbody>
265→        </table>
266→      </div>
267→
268→      {/* Legend + message */}
269→      <div style={{ display: "flex", gap: 16, marginTop: 12, fontSize: 11, color: "var(--text-secondary)", alignItems: "center", flexWrap: "wrap" }}>
270→        <div style={{ display: "flex", alignItems: "center", gap: 4 }}>
271→          <div style={{ width: 14, height: 14, background: "var(--primary-green)", borderRadius: 3, display: "flex", alignItems: "center", justifyContent: "center" }}>
272→            <span style={{ color: "#fff", fontSize: 9 }}>&#10003;</span>
273→          </div>
274→          허용
275→        </div>
276→        <div style={{ display: "flex", alignItems: "center", gap: 4 }}>
277→          <div style={{ width: 14, height: 14, background: "#e0e0e0", borderRadius: 3 }} />
278→          차단
279→        </div>
280→        <span style={{ color: "var(--text-disabled)" }}>|</span>
281→        <span>클릭하여 토글</span>
282→        {message && (
283→          <span style={{ marginLeft: "auto", color: "var(--primary-green)", fontWeight: 500 }}>
284→            {message}
285→          </span>
286→        )}
287→      </div>
288→    </div>
289→  );
290→}
