 1→import { requireUser, listUsers } from "@/lib/auth";
 2→import { checkPermission } from "@/lib/permissions";
 3→import { redirect } from "next/navigation";
 4→import { getDepartmentOptions } from "@/lib/queries";
 5→import { UserAdminPanel } from "@/components/user-admin-panel";
 6→
 7→export default async function UsersPage() {
 8→  const user = await requireUser();
 9→  if (!checkPermission(user.role, "system.users", "view")) {
10→    redirect("/summary");
11→  }
12→
13→  const users = listUsers();
14→  const departments = getDepartmentOptions();
15→
16→  return (
17→    <div>
18→      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 20 }}>
19→        <div>
