21→            사용자 관리
22→          </h2>
23→          <p style={{ fontSize: 12, color: "var(--text-secondary)", margin: "2px 0 0" }}>
24→            시스템 사용자 계정을 관리합니다
25→          </p>
26→        </div>
27→      </div>
28→      <UserAdminPanel initialUsers={users} departments={departments} />
29→    </div>
30→  );
31→}
