 1→import { requireUser } from "@/lib/auth";
 2→import { checkPermission, getAllRoles, getPermissionsForRole } from "@/lib/permissions";
 3→import { redirect } from "next/navigation";
 4→import PermissionMatrix from "@/components/permission-matrix";
 5→
 6→export default async function PermissionsPage() {
 7→  const user = await requireUser();
 8→  if (!checkPermission(user.role, "system.permissions", "view")) {
 9→    redirect("/summary");
10→  }
11→
12→  const roles = getAllRoles();
13→  const permissions: Record<string, { resource: string; action: string; allowed: boolean }[]> = {};
14→  for (const role of roles) {
15→    permissions[role] = getPermissionsForRole(role);
16→  }
17→
18→  return (
19→    <div>
20→      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 20 }}>
21→        <div>
22→          <h2 style={{ fontSize: 18, fontWeight: 600, color: "var(--text-title)", margin: 0 }}>
23→            권한 관리
24→          </h2>
25→          <p style={{ fontSize: 12, color: "var(--text-secondary)", margin: "2px 0 0" }}>
26→            역할별 페이지/기능 접근 권한을 관리합니다
27→          </p>
28→        </div>
29→      </div>
30→      <PermissionMatrix roles={roles} permissions={permissions} />
31→    </div>
32→  );
33→}
