  1→import { getDb } from "./db";
  2→
  3→export function checkPermission(
  4→  role: string,
  5→  resource: string,
  6→  action: string
  7→): boolean {
  8→  const db = getDb();
  9→
 10→  // 먼저 와일드카드 '*' 체크
 11→  const wildcard = db
 12→    .prepare(
 13→      "SELECT allowed FROM permissions WHERE role = ? AND resource = '*' AND action = ? LIMIT 1"
 14→    )
 15→    .get(role, action) as { allowed: number } | undefined;
 16→
 17→  if (wildcard) return wildcard.allowed === 1;
 18→
 19→  // 정확한 resource 체크
 20→  const exact = db
 21→    .prepare(
 22→      "SELECT allowed FROM permissions WHERE role = ? AND resource = ? AND action = ? LIMIT 1"
 23→    )
 24→    .get(role, resource, action) as { allowed: number } | undefined;
 25→
 26→  if (exact) return exact.allowed === 1;
 27→
 28→  // 권한 레코드가 없으면 거부
 29→  return false;
 30→}
 31→
 32→export function getPermissionsForRole(role: string): {
 33→  resource: string;
 34→  action: string;
 35→  allowed: boolean;
 36→}[] {
 37→  const db = getDb();
 38→  const rows = db
 39→    .prepare("SELECT resource, action, allowed FROM permissions WHERE role = ?")
 40→    .all(role) as { resource: string; action: string; allowed: number }[];
 41→  return rows.map((r) => ({
 42→    resource: r.resource,
 43→    action: r.action,
 44→    allowed: r.allowed === 1,
 45→  }));
 46→}
 47→
 48→export function updatePermissions(
 49→  role: string,
 50→  changes: { resource: string; action: string; allowed: boolean }[]
 51→): void {
 52→  const db = getDb();
 53→  const upsert = db.prepare(`
 54→    INSERT INTO permissions (role, resource, action, allowed)
 55→    VALUES (?, ?, ?, ?)
 56→    ON CONFLICT(role, resource, action)
 57→    DO UPDATE SET allowed = excluded.allowed, updated_at = CURRENT_TIMESTAMP
 58→  `);
 59→  const tx = db.transaction(() => {
 60→    for (const c of changes) {
 61→      upsert.run(role, c.resource, c.action, c.allowed ? 1 : 0);
 62→    }
 63→  });
 64→  tx();
 65→}
 66→
 67→export function getAllRoles(): string[] {
 68→  const db = getDb();
 69→  const rows = db
 70→    .prepare("SELECT DISTINCT role FROM permissions ORDER BY role")
 71→    .all() as { role: string }[];
 72→  return rows.map((r) => r.role);
 73→}
 74→
 75→export function createRole(role: string): void {
 76→  const db = getDb();
 77→  const RESOURCES = [
 78→    "dashboard",
 79→    "candidates",
 80→    "procedures", "actions",
 81→    "admin.data",
 82→    "system.permissions", "system.users",
 83→    "workflow.review", "workflow.advance",
 84→    "etc",
 85→  ];
 86→  const ACTIONS = ["view", "edit", "delete", "export", "import"];
 87→  const insert = db.prepare(
 88→    "INSERT OR IGNORE INTO permissions (role, resource, action, allowed) VALUES (?, ?, ?, 0)"
 89→  );
 90→  const tx = db.transaction(() => {
 91→    for (const resource of RESOURCES) {
 92→      for (const action of ACTIONS) {
 93→        insert.run(role, resource, action);
 94→      }
 95→    }
 96→  });
 97→  tx();
 98→}
 99→
100→export function deleteRole(role: string): { success: boolean; error?: string } {
101→  const db = getDb();
102→  const userCount = db
103→    .prepare("SELECT COUNT(*) as count FROM users WHERE role = ?")
104→    .get(role) as { count: number };
105→  if (userCount.count > 0) {
106→    return { success: false, error: `${userCount.count}명의 사용자가 이 역할을 사용 중입니다.` };
107→  }
108→  db.prepare("DELETE FROM permissions WHERE role = ?").run(role);
109→  return { success: true };
110→}
111→
112→export function getViewableResources(role: string): string[] {
113→  const db = getDb();
114→
115→  // 와일드카드 체크
116→  const wildcard = db
117→    .prepare("SELECT allowed FROM permissions WHERE role = ? AND resource = '*' AND action = 'view'")
118→    .get(role) as { allowed: number } | undefined;
119→
120→  if (wildcard?.allowed === 1) {
121→    return [
122→      "dashboard",
123→      "candidates",
124→      "procedures", "actions",
125→      "admin.data",
126→      "system.permissions", "system.users",
127→      "workflow.review", "workflow.advance",
128→    ];
129→  }
130→
131→  const rows = db
132→    .prepare("SELECT resource FROM permissions WHERE role = ? AND action = 'view' AND allowed = 1")
133→    .all(role) as { resource: string }[];
134→  return rows.map((r) => r.resource);
135→}
