 71→export function createUser(payload: {
 72→  username: string;
 73→  password: string;
 74→  role: UserRole;
 75→  departmentCode: string | null;
 76→}) {
 77→  const db = getDb();
 78→  const passwordHash = hashPassword(payload.password);
 79→  const result = db
 80→    .prepare(
 81→      `INSERT INTO users (username, password, role, department_code)
 82→       VALUES (?, ?, ?, ?)`,
 83→    )
 84→    .run(payload.username, passwordHash, payload.role, payload.departmentCode);
 85→
 86→  return getUserById(Number(result.lastInsertRowid));
 87→}
