                      </p>
                      <p style={{ marginTop: 3, fontSize: 11, color: "var(--text-secondary)", margin: "3px 0 0" }}>
                        {user.departmentCode ?? "전체"}
                      </p>
                    </div>
                    <span
                      className={getRoleBadgeClass(user.role)}
                      style={{ fontSize: 10, padding: "2px 8px", borderRadius: 10 }}
                    >
                      {user.role}
                    </span>
                  </div>
                </div>
              );
            })}
          </div>
        </div>

        {/* Right: Permission panel */}
        <div style={{ flex: 1, minWidth: 0 }} className="perm-panel-col">
          {!selectedUser ? (
            <div
              className="card"
              style={{
                padding: "60px 20px",
                textAlign: "center",
                background: "var(--row-hover)",
                border: "1px solid var(--divider)",
              }}
            >
              <p style={{ fontSize: 14, color: "var(--text-secondary)", margin: 0 }}>
                좌측에서 사용자를 선택하면 권한을 설정할 수 있습니다
              </p>
            </div>
          ) : (
            <div>
              {/* Selected user header */}
              <div
                className="card"
                style={{
                  padding: "14px 18px",
                  marginBottom: 16,
                  background: "var(--row-hover)",
                  border: "1px solid var(--divider)",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "space-between",
                  flexWrap: "wrap",
                  gap: 12,
                }}
              >
                <div>
                  <p style={{ fontSize: 15, fontWeight: 600, color: "var(--text-title)", margin: 0 }}>
                    {selectedUser.username}
                  </p>
                  <p style={{ fontSize: 12, color: "var(--text-secondary)", margin: "4px 0 0" }}>
                    현재 역할: <strong>{selectedUser.role}</strong>
                    {selectedUser.departmentCode ? ` · ${selectedUser.departmentCode}` : ""}
                  </p>
                </div>
                <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
                  <span style={{ fontSize: 11, color: "var(--text-secondary)", alignSelf: "center", marginRight: 4 }}>
                    등급 프리셋:
                  </span>
                  {ROLES.map((role) => (
                    <button
                      key={role}
                      onClick={() => handlePresetClick(role)}
                      className={selectedUser.role === role ? "btn-primary" : "btn-secondary"}
                      style={{ fontSize: 11, padding: "5px 14px" }}
                    >
                      {role}
                    </button>
                  ))}
                </div>
              </div>

              {/* Permission matrix */}
              <div className="card" style={{ padding: 0, overflow: "hidden", border: "1px solid var(--divider)" }}>
                <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 12 }}>
                  <thead>
                    <tr style={{ background: "var(--header-bg)" }}>
                      <th
                        style={{
                          textAlign: "left",
                          padding: "10px 14px",
                          color: "var(--text-secondary)",
                          fontWeight: 500,
                          fontSize: 11,
                          width: "30%",
                        }}
                      >
                        리소스
                      </th>
                      {ACTIONS.map((a) => (
                        <th
                          key={a.key}
                          style={{
                            textAlign: "center",
                            padding: "10px 14px",
                            color: "var(--text-secondary)",
                            fontWeight: 500,
                            fontSize: 11,
                            width: "14%",
                          }}
                        >
                          {a.label}
                        </th>
                      ))}
                    </tr>
                  </thead>
                  <tbody>
                    {RESOURCE_GROUPS.map((group) => (
                      <tbody key={group.title}>
                        <tr style={{ background: "var(--header-bg)" }}>
                          <td
                            colSpan={6}
                            style={{
                              padding: "8px 14px",
                              fontSize: 10,
                              color: "var(--text-secondary)",
                              fontWeight: 600,
                              textTransform: "uppercase",
                              letterSpacing: 0.5,
                            }}
                          >
                            {group.title}
                          </td>
                        </tr>
                        {group.resources.map((res) => (
                          <tr key={res.key} style={{ borderTop: "1px solid var(--divider)" }}>
                            <td style={{ padding: "10px 14px", color: "var(--text-body)" }}>
                              {res.label}
                            </td>
                            {ACTIONS.map((action) => {
                              const allowed = isAllowed(activeRole, res.key, action.key);
                              return (
                                <td key={action.key} style={{ textAlign: "center", padding: "10px 14px" }}>
                                  <div
                                    onClick={() => toggle(res.key, action.key)}
                                    style={{
                                      width: 18,
                                      height: 18,
                                      background: allowed ? "var(--primary-green)" : "#e0e0e0",
                                      borderRadius: 4,
                                      margin: "0 auto",
                                      display: "flex",
                                      alignItems: "center",
                                      justifyContent: "center",
                                      cursor: "pointer",
                                    }}
                                  >
                                    {allowed && (
                                      <span style={{ color: "#fff", fontSize: 11 }}>&#10003;</span>
                                    )}
                                  </div>
                                </td>
                              );
                            })}
                          </tr>
                        ))}
                      </tbody>
                    ))}
                  </tbody>
                </table>
              </div>

              {/* Legend + save */}
              <div
                style={{
                  display: "flex",
                  gap: 16,
                  marginTop: 12,
                  fontSize: 11,
                  color: "var(--text-secondary)",
                  alignItems: "center",
                  flexWrap: "wrap",
                }}
              >
                <div style={{ display: "flex", alignItems: "center", gap: 4 }}>
                  <div
                    style={{
                      width: 14,
                      height: 14,
                      background: "var(--primary-green)",
                      borderRadius: 3,
                      display: "flex",
                      alignItems: "center",
                      justifyContent: "center",
                    }}
                  >
                    <span style={{ color: "#fff", fontSize: 9 }}>&#10003;</span>
                  </div>
                  허용
                </div>
                <div style={{ display: "flex", alignItems: "center", gap: 4 }}>
                  <div style={{ width: 14, height: 14, background: "#e0e0e0", borderRadius: 3 }} />
                  차단
                </div>
